/* NEXA Troop Assets V24 — ARTWORK OWNER
   No runtime observers. No legacy polish loader.
   Complete Infantry/Lancer/Marksman T1–T12 + Fire Crystal badges FC1–FC10.
*/
(()=>{
'use strict';
if(window.__NEXA_TROOP_ASSETS_V24__) return;
window.__NEXA_TROOP_ASSETS_V24__=true;
const portraits={"infantry":{"t1":"/nexa-troop-infantry-t1.webp?v=24","t2":"/nexa-troop-infantry-t2.webp?v=24","t3":"/nexa-troop-infantry-t3.webp?v=24","t4":"/nexa-troop-infantry-t4.webp?v=24","t5":"/nexa-troop-infantry-t5.webp?v=24","t6":"/nexa-troop-infantry-t6.webp?v=24","t7":"/nexa-troop-infantry-t7.webp?v=24","t8":"/nexa-troop-infantry-t8.webp?v=24","t9":"/nexa-troop-infantry-t9.webp?v=24","t10":"/nexa-troop-infantry-t10.webp?v=24","t11":"/nexa-troop-infantry-t11.webp?v=24","t12":"/nexa-troop-infantry-t12.webp?v=24"},"lancer":{"t1":"/nexa-troop-lancer-t1.webp?v=24","t2":"/nexa-troop-lancer-t2.webp?v=24","t3":"/nexa-troop-lancer-t3.webp?v=24","t4":"/nexa-troop-lancer-t4.webp?v=24","t5":"/nexa-troop-lancer-t5.webp?v=24","t6":"/nexa-troop-lancer-t6.webp?v=24","t7":"/nexa-troop-lancer-t7.webp?v=24","t8":"/nexa-troop-lancer-t8.webp?v=24","t9":"/nexa-troop-lancer-t9.webp?v=24","t10":"/nexa-troop-lancer-t10.webp?v=24","t11":"/nexa-troop-lancer-t11.webp?v=24","t12":"/nexa-troop-lancer-t12.webp?v=24"},"marksman":{"t1":"/nexa-troop-marksman-t1.webp?v=24","t2":"/nexa-troop-marksman-t2.webp?v=24","t3":"/nexa-troop-marksman-t3.webp?v=24","t4":"/nexa-troop-marksman-t4.webp?v=24","t5":"/nexa-troop-marksman-t5.webp?v=24","t6":"/nexa-troop-marksman-t6.webp?v=24","t7":"/nexa-troop-marksman-t7.webp?v=24","t8":"/nexa-troop-marksman-t8.webp?v=24","t9":"/nexa-troop-marksman-t9.webp?v=24","t10":"/nexa-troop-marksman-t10.webp?v=24","t11":"data:image/webp;base64,","t12":"data:image/webp;base64,"}};
const fireCrystal={"1":"data:image/webp;base64,","2":"data:image/webp;base64,","3":"data:image/webp;base64,","4":"data:image/webp;base64,","5":"data:image/webp;base64,","6":"data:image/webp;base64,","7":"data:image/webp;base64,","8":"data:image/webp;base64,","9":"data:image/webp;base64,","10":"data:image/webp;base64,"};
window.NEXA_TROOP_PORTRAITS=portraits;
window.NEXA_FIRE_CRYSTAL_BADGES=fireCrystal;
window.NEXA_TROOP_ASSETS={
 portraits,fireCrystal,
 getPortrait(type,tier){const key=String(type||'').toLowerCase().replace(/[^a-z]/g,'');const t='t'+String(tier||'').replace(/\D/g,'');return portraits[key]?.[t]||''},
 getFireCrystal(level){const n=String(level||'').replace(/\D/g,'');return fireCrystal[n]||''}
};

function normalizeType(v){return String(v||'').toLowerCase().replace(/[^a-z]/g,'')}
function ownLibraryTroopArt(){
 if(!/library\.html$/i.test(location.pathname))return;
 document.querySelectorAll('.lib-card').forEach(card=>{
  const row=card.querySelector('[data-troop-type]');if(!row)return;
  const type=normalizeType(row.dataset.troopType);
  if(!portraits[type])return;
  let active=row.querySelector('.troop-tier.active');
  if(!row.dataset.nexaTroopOwned){
    row.dataset.nexaTroopOwned='24';
    row.querySelectorAll('.troop-tier').forEach(b=>b.classList.remove('active'));
    active=row.querySelector('[data-tier="1"]')||row.querySelector('.troop-tier');
    active?.classList.add('active');
  }
  const tier=Number(active?.dataset.tier||1);
  const img=card.querySelector('[data-lib-troop-img],.lib-img.troop');
  const src=portraits[type]?.['t'+tier];
  if(img&&src&&img.getAttribute('src')!==src)img.setAttribute('src',src);
 });
}
document.addEventListener('click',e=>{
 if(!/library\.html$/i.test(location.pathname))return;
 const b=e.target.closest?.('.troop-tier[data-tier]');if(!b)return;
 const row=b.closest('[data-troop-type]'),card=b.closest('.lib-card');if(!row||!card)return;
 const type=normalizeType(row.dataset.troopType),tier=Number(b.dataset.tier||1),src=portraits[type]?.['t'+tier];
 if(!src)return;
 e.preventDefault();e.stopImmediatePropagation();
 row.dataset.nexaTroopOwned='24';
 row.querySelectorAll('.troop-tier').forEach(x=>x.classList.toggle('active',x===b));
 const img=card.querySelector('[data-lib-troop-img],.lib-img.troop');if(img)img.src=src;
},true);
function bootTroopArtOwner(){
 ownLibraryTroopArt();
 [200,500,900,1500,2400,3600,5200].forEach(ms=>setTimeout(ownLibraryTroopArt,ms));
 document.getElementById('tabs')?.addEventListener('click',()=>[80,220,500].forEach(ms=>setTimeout(ownLibraryTroopArt,ms)));
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bootTroopArtOwner,{once:true});else bootTroopArtOwner();
})();